import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Form Proposal workspace","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/index.md","filePath":"proposals/index.md"}'),o={name:"proposals/index.md"};function r(n,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="form-proposal-workspace" tabindex="-1">Form Proposal workspace <a class="header-anchor" href="#form-proposal-workspace" aria-label="Permalink to &quot;Form Proposal workspace&quot;">​</a></h1><p>This directory contains mutable design material for Forms that have not earned a public FormRef. A document here is not a package, release, maturity claim, Host Support decision, or Service Offering.</p><p>Family design work lives in per-family subdirectories, authored under the shape-preserving boundary of <a href="./../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a> and selected by <a href="./../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>:</p><ul><li><a href="./edge/">Edge Platform Family</a> — the first family; its candidates are tracked by <a href="../forms/candidates/edge/v1beta1/candidate-set.json"><code>../forms/candidates/edge/v1beta1/candidate-set.json</code></a>, and its Beta 2 additions (<code>DurableWorkflow</code>, <code>ActorNamespace</code>) are proposed in this tree.</li><li><a href="./function/">Regional Function Family</a> — regional FaaS.</li><li><a href="./container/">Serverless Container Family</a> — OCI-image services.</li><li><a href="./table/">Table Family</a> — key-addressed document tables.</li><li><a href="./queue/">Pull Queue Family</a> — pull-based at-least-once queues.</li><li><a href="./topic/">Topic Family</a> — fanout topics with push subscriptions.</li><li><a href="./schedule/">Schedule Family</a> — standalone cron invocation.</li><li><a href="./vector/">Vector Family</a> — fixed-dimension vector indexes.</li></ul><p>The seven new families are proposals only: no candidate set exists yet, and a proposal reserves no public identity. The pre-family flat Proposal set and its lifecycle registry were withdrawn with the pre-Beta epochs (<a href="./../spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); their documents stay in git history as design provenance and reserve no public identity.</p><p>Start a new family Proposal by copying <code>TEMPLATE.md</code> into the family&#39;s subdirectory under a descriptive lowercase filename. A Form enters the family only through the generated candidate set; the public-surface gate holds every hand-written inventory to that roster, so a Proposal without a candidate entry cannot leak into the published surface.</p><p>Before review, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/standard-form-conformance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>Proposal review does not authorize publication. When a Proposal is withdrawn, remove its document unless a decision record needs to retain the design history; no public identity is reserved by a withdrawn Proposal.</p>',9)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
